import subprocess
from pathlib import Path


def count_lines(directory: Path, filename: str) -> int:
    completed = subprocess.run(f"wc -l < {filename}", shell=True, cwd=directory,
                               capture_output=True, text=True, check=True)
    return int(completed.stdout.strip())
